#include<bits/stdc++.h>
#define mod 998244353
#define inv2 499122177 // inverse of 2

using namespace std;

// A_1 = fir
// A_i = fir + (i-1) * d
// return A_1 + A_2 + ... + A_{num}
long long arithmetic_sum(long long fir,long long d,long long num){
  long long las=(fir+(num-1)*d)%mod;
  long long res=(fir+las)%mod;
  res*=num;res%=mod;
  res*=inv2;res%=mod;
  return res;
}

using pl=pair<long long,long long>;

long long n,m;
pl row_data(long long x,long long l,long long r){
  if((x+l)%2){l++;}
  if((x+r)%2){r--;}
  if(l>r){return {0,0};}

  long long mi=((x-1)*m+l)%mod;
  long long num=1+(r-l)/2;
  long long sum=arithmetic_sum(mi,2,num);

  num*=2;num%=mod;
  num*=m;num%=mod;
  return {sum,num};
}

int main(){
  int q;
  cin >> n >> m >> q;
  for(int i=0;i<q;i++){
    long long a,b,c,d;
    cin >> a >> b >> c >> d;

    pl r1=row_data(a,c,d);
    pl r2=row_data(a+1,c,d);
    long long c1=(b-a+1)/2 + (b-a+1)%2;
    long long c2=(b-a+1)/2;
    long long res=0;
    res+=arithmetic_sum(r1.first,r1.second,c1);res%=mod;
    res+=arithmetic_sum(r2.first,r2.second,c2);res%=mod;
    cout << res << "\n";
  }
  return 0;
}

#include <bits/stdc++.h>

#include <atcoder/modint>

using namespace std;
using mint = atcoder::modint998244353;
using ll = long long;

int n, m;
mint f(int a, int b, int c, int d) {
    if(a > b or c > d) return 0;
    if(((b - a) ^ (d - c)) & 1) {
        if((d - c) & 1)
            return f(a, b, c, d - 1) + f(a, b, d, d);
        else
            return f(a, b - 1, c, d) + f(b, b, c, d);
    }
    mint ave = (mint(a + b) / 2 - 1) * m + mint(c + d) / 2;
    mint cnt = (ll)(b - a + 1) * (d - c + 1) / 2;
    if(!((b - a) & 1) and !((a + c) & 1)) cnt++;
    return ave * cnt;
}

int main() {
    cin >> n >> m;
    int q;
    cin >> q;
    while(q--) {
        int a, b, c, d;
        cin >> a >> b >> c >> d;
        cout << f(a, b, c, d).val() << endl;
    }
}
